  }) }}

={{ ({
  model: "gpt-5.4-mini",
  store: false,
  max_output_tokens: 1100,
  instructions: "You are an AI automation market analyst. Extract only from the supplied opportunity. Do not invent facts. Use not_specified for unavailable enum/string values and [] for arrays. Keep analysis values concise and in English, except content_angle, which must be a concise Ukrainian B2B content idea based only on the supplied opportunity. title_ua, client_problem_ua, and potential_service_ua must be faithful Ukrainian translations of title, client_problem, and potential_service respectively; do not add facts. Set n8n_implementation_applicable true only when n8n can be the primary orchestration layer for a realistic implementation (APIs, webhooks, integrations, data movement, scheduled workflows, LLM/AI agents, CRM, databases, spreadsheets, messaging, or similar). If false, implementation_plan and implementation_plan_ua MUST be empty strings. If true, implementation_plan must be a concise 3-6 step implementation plan in English, and implementation_plan_ua its faithful Ukrainian translation. Plans must describe only the requested solution and name n8n's role; do not invent systems, credentials, or requirements.",
  input: "Title: " + ($json["title (Назва проєкту або вакансії)"] ?? "") + "\n\nDescription: " + ($json["description (Опис)"] ?? ""),
  text: { format: { type: "json_schema", name: "demand_signals", strict: true, schema: { type: "object", additionalProperties: false, properties: { client_problem: { type: "string" }, automation_type: { type: "string", enum: ["ai_agent", "workflow_automation", "system_integration", "lead_generation", "customer_support", "content_automation", "data_research", "other"] }, technologies: { type: "array", items: { type: "string" } }, required_skills: { type: "array", items: { type: "string" } }, client_type: { type: "string", enum: ["business_owner", "agency", "startup", "enterprise", "individual", "not_specified"] }, project_scope: { type: "string", enum: ["one_off", "ongoing", "pilot", "not_specified"] }, potential_service: { type: "string" }, content_angle: { type: "string" }, n8n_implementation_applicable: { type: "boolean" }, implementation_plan: { type: "string" }, implementation_plan_ua: { type: "string" }, title_ua: { type: "string" }, client_problem_ua: { type: "string" }, potential_service_ua: { type: "string" }, confidence: { type: "number", minimum: 0, maximum: 1 } }, required: ["client_problem", "automation_type", "technologies", "required_skills", "client_type", "project_scope", "potential_service", "content_angle", "n8n_implementation_applicable", "implementation_plan", "implementation_plan_ua", "title_ua", "client_problem_ua", "potential_service_ua", "confidence"] } } }
}) }}

parameters.jsCode:
const safeItems = (nodeName) => {
  try { return $(nodeName).all(); } catch { return []; }
};
const sumField = (nodeName, fieldName) =>
  safeItems(nodeName).reduce((sum, item) => sum + Number(item.json[fieldName] ?? 0), 0);

const run = $('Prepare demand run start').first().json;
const inputItems = safeItems('Read opportunities').length;
const validItems = safeItems('Filter valid opportunities').length;
const projectItems = safeItems('Keep client projects').length;
const intentCalls = safeItems('Normalize opportunity intent usage').length;
const analysisCalls = safeItems('Normalize demand signals usage').length;
const inputTokens = sumField('Normalize opportunity intent usage', 'intent_input_tokens') + sumField('Normalize demand signals usage', 'analysis_input_tokens');
const cachedInputTokens = sumField('Normalize opportunity intent usage', 'intent_cached_input_tokens') + sumField('Normalize demand signals usage', 'analysis_cached_input_tokens');
const outputTokens = sumField('Normalize opportunity intent usage', 'intent_output_tokens') + sumField('Normalize demand signals usage', 'analysis_output_tokens');
const totalTokens = sumField('Normalize opportunity intent usage', 'intent_total_tokens') + sumField('Normalize demand signals usage', 'analysis_total_tokens');

const INPUT_RATE_PER_MILLION = 0.75;
const CACHED_INPUT_RATE_PER_MILLION = 0.075;
const OUTPUT_RATE_PER_MILLION = 4.5;
const estimatedCostUsd = Number((
  (Math.max(0, inputTokens - cachedInputTokens) / 1_000_000) * INPUT_RATE_PER_MILLION +
  (cachedInputTokens / 1_000_000) * CACHED_INPUT_RATE_PER_MILLION +
  (outputTokens / 1_000_000) * OUTPUT_RATE_PER_MILLION
).toFixed(8));
const finishedAt = $now.toISO();
const durationSeconds = Math.max(0, Math.round($now.diff(DateTime.fromISO(run.started_at), 'seconds').seconds));

return [{ json: {
  'run_id (ID запуску)': run.run_id,
  'n8n_execution_id (ID виконання n8n)': run.n8n_execution_id,
  'workflow_name (Назва workflow)': run.workflow_name,
  'workflow_category (Категорія workflow)': run.workflow_category,
  'trigger_type (Тип запуску)': run.trigger_type,
  'started_at (Час початку)': run.started_at,
  'finished_at (Час завершення)': finishedAt,
  'duration_seconds (Тривалість, сек)': durationSeconds,
  'run_status (Статус запуску)': 'success',
  'items_input (Вхідних записів)': inputItems,
  'items_processed (Оброблено записів)': projectItems,
  'items_created (Створено записів)': 0,
  'items_updated (Оновлено записів)': projectItems,
  'items_skipped (Пропущено записів)': Math.max(0, validItems - projectItems),
  'items_failed (Помилок записів)': 0,
  'ai_calls (AI-викликів)': intentCalls + analysisCalls,
  'model_name (AI-модель)': 'gpt-5.4-mini',
  'input_tokens (Вхідні токени)': inputTokens,
  'output_tokens (Вихідні токени)': outputTokens,
  'total_tokens (Усього токенів)': totalTokens,
  'estimated_cost_usd (Орієнтовна вартість, USD)': estimatedCostUsd,
  'error_message (Повідомлення про помилку)': '',
  'run_metadata (Додаткові дані JSON)': JSON.stringify({
    intent_calls: intentCalls, demand_analysis_calls: analysisCalls,
    cached_input_tokens: cachedInputTokens,
    pricing_usd_per_million: { input: INPUT_RATE_PER_MILLION, cached_input: CACHED_INPUT_RATE_PER_MILLION, output: OUTPUT_RATE_PER_MILLION },
    method: 'OpenAI Responses API actual usage',
  }),
}}];
